const data = $json.data;
const eventFolderCode = $('Get Event Folder Code').item.json.folder_code;
const inboundMessageId = $('Claim Photo Message').item.json.id;
const source = data.sourceType === 'directory_listing' ? 'directory_photo' : undefined;
return data.cards.map((card) => ({ json: {
  eventFolderCode: eventFolderCode,
  firstName: card.firstName, lastName: card.lastName, email: card.email, phone: card.phone,
  title: card.title, districtName: card.districtName, schoolName: card.schoolName,
  extractionConfidence: card.extractionConfidence, sourceImageHash: card.sourceImageHash,
  sourceImagePath: $('Claim Photo Message').item.json.storage_path,
  croppedImagePath: card.croppedImagePath || null,
  inboundMessageId: inboundMessageId,
  source: source || null,
} }));

const items = $input.all();
const created = items.filter((i) => i.json.created).length;
const failures = items.filter((i) => !i.json.created).map((i) => i.json.label + ': ' + i.json.error);
const allFailed = failures.length > 0 && created === 0;
return [{ json: {
  status: allFailed ? 'failed' : 'completed',
  error: failures.length > 0 ? failures.join('; ') : null,
} }];

const TERMINAL_ERROR_PATTERNS = [/no legible business card detected/i, /refusing to (build a prompt|upload)/i];
const message = $json.error || 'unknown error';
const errorClass = TERMINAL_ERROR_PATTERNS.some((re) => re.test(message)) ? 'terminal' : 'transient';
return [{ json: { errorMessage: message, errorClass: errorClass } }];
